  w6_calib: MS(['בחר מינימום־מקסימום עם פיקסלים שרופים: פי כמה גדולה השגיאה מהאחוזון?', 'הורד את האחוזון ל־95: כמה נחתך, ומה קרה לשגיאה?', 'בחר "חיפוש": איפה הוא חתך?', 'סמן "הערכה בלילה": מה קרה לשגיאה, ולמה?'], 'הטווח נבחר על סט הכיול ונבחן על סט אחר; חריג אחד הורס מינימום־מקסימום, חיתוך מוגזם חותך ערכים אמיתיים, וסט שלא מייצג את השטח טועה בכל השיטות.'),
  w6_ste: MS(['הרץ את שלושת השלבים: מה הדיוק אחרי כל אחד?', 'הסתכל על המשקל לאורך האימון: מתי הכתום קופץ?', 'אמן מחדש, כבה את האומדן והרץ שוב: מה זז ומה לא?', 'נסה 3 ביטים: כמה נפל הכימום אחרי אימון?'], 'אימון מודע כימום מעדכן משקלות מקוריים בצעדים קטנים עד שהמכומם קופץ; בלי האומדן המשקלות לא זזים.'),
  w6_int8_speed: MS(['על המעבד של הקורס: מה נקודת האיזון?', 'עבור למעבד ישן: האם שמונה ביטים משתלמים בכלל?', 'בכרטיס עם ליבות טנזור: איפה האיזון, ולמה הוא נמוך יותר?'], 'שמונה ביטים = מחיר קבוע + חישוב מואץ; מתחת לנקודת האיזון — ובחומרה בלי תמיכה — הם מאטים.'),
  w6_loop_vs_threads: MS(['בניסוי של הקורס: השווה את שלושת המבנים לטבלה של הקורס.', 'לחץ "הסקה של 20 מ"ש": מה קרה ללולאה?', 'סמן את הנעילה: מה קרה לתהליכונים?', 'העלה את המצלמה ל־60: מה עמד ומה נשבר?'], 'לולאה איטית מהמצלמה רואה את העבר; תהליכונים מעלים תפוקה; רק התור של החדש חוסם את ההשהייה — וכל זה רק כשהעבודה משחררת את הנעילה.'),
  w6_queue_sim: MS(['כמה פריימים נזרקו בשתי שניות, ומה הפערים?', 'כמה ניבויים שגויים יש לעוקב שמניח 33 מ"ש?', 'סמן "הזמן האמיתי": מה השתנה?', 'הורד את המודל ל־30 מ"ש: מה קרה?'], 'תור של החדש זורק פריימים ומשנה את הפער בזמן; העוקב חייב לקבל את הזמן האמיתי.'),
  w6_file_vs_cam: MS(['בתור שזורק: כמה פריימים מהקובץ אבדו?', 'בתור שמחכה, גודל 1 מול 4: מה הקצב?', 'שני גרעינים ושני תהליכוני מודל: כמה הרוויח הפענוח הנפרד?', 'סמן מודל על כרטיס: כמה עכשיו?'], 'לקובץ — תור שמחכה; ופיצול לתהליכונים מרוויח רק כשיש משאבים פנויים.'),
  w6_amdahl: MS(['האץ את ההסקה פי 2 ופי 20: מה הצינור, ומה התקרה?', 'האץ את הפענוח פי 20: כמה הרוויח הצינור?', 'הורד את ההסקה ל־3 מ"ש (אחרי האצה): עכשיו מה הצוואר?', 'בטבלה: איזו קונבולוציה "חורגת" מהיחס בין כפלות לזמן?'], 'האצה מועילה כפרופורציה לחלק של השלב; אחרי שהמודל מואץ, הצוואר זז לפענוח ולעיבוד המקדים.'),
  w6_async_clock: MS(['בלי סנכרון: מה מראה שעון ההסקה, ומה שעון העיבוד המאוחר?', 'סמן סנכרון: האם המספרים נכונים עכשיו?', 'מה ניצולת הכרטיס? הגדל את הפענוח ל־10: מה קרה?', 'סמן חפיפה: מה קרה לניצולת ולזמן הכולל?'], 'כרטיס אסינכרוני דורש סנכרון כשמודדים; ניצולת נמוכה פירושה שהכרטיס מחכה למעבד — וחפיפה מתקנת.'),
  w6_preproc_order: MS(['לחץ "מדוד": פי כמה איטי הנרמול קודם?', 'סמן 4K ומדוד שוב: מה קרה ליחס?', 'השווה לעמודה של הקורס: מה דומה ומה שונה?'], 'הסדר קובע כמה בתים זזים — להקטין קודם ולנרמל אחר כך; והמספר המוחלט תלוי במחשב, היחס פחות.'),
  w6_decode: MS(['1080 על המחשב הנייד: כמה מגרעין הולך על פענוח?', '4K על Jetson, בתוכנה: האם עומדים בקצב?', 'הדלק מפענח בחומרה: מה נשאר על המעבד?', 'כבה את המרת הצבע: כמה עכשיו?'], 'פענוח בתוכנה גדל עם הפיקסלים; מפענח בחומרה חוסך אותו — אבל המרת הצבע על המעבד נשארת, ומודדים אותה.'),
  w6_transfer: MS(['ב־1080: כמה MB בשנייה עוברים בכל דרך?', 'עבור ל־4K: מה גדל, ומה לא?', 'סמן Jetson: מה קרה לזמני ההעתקה?'], 'מה שעובר לכרטיס הוא הטנזור, לא הפריים; שמונה ביטים מקטינים אותו פי ארבעה, ושיתוף זיכרון חוסך העתקות.'),
  w6_java_cpp: MS(['כמה עצירות איסוף ב־600 פריימים, ומה אחוזון 99?', 'הגדל את הערימה ל־2048: מה קרה למספר העצירות ולגודלן?', 'מה עולה להעביר ווקטור של 10 מיליון לפי ערך?'], 'מנקה הזבל יוצר זנב לא צפוי; ב־C++ השחרור דטרמיניסטי — אבל העתקות ודליפות הן באחריותך.'),
  w6_assoc: MS(['מה ההבדל בין שלושת הסדרים בעשרוני? איזה הכי מדויק?', 'שנה את מספר המסלולים: מה קורה לתוצאה בעשרוני, ומה בשלמים?', 'הקטן ל־2^10 איברים: מה קרה להבדלים?'], 'סדר החיבור משנה תוצאה בעשרוני — לכן המהדר לא ימקבל; בשלמים לא — לכן כן.'),
  w6_raii: MS(['בשחרור ידני, פעם ב־100: מתי נגמר הזיכרון?', 'פעם ב־2000: האם יופיע בבדיקה של עשר דקות?', 'עבור ל־RAII: מה קרה?', 'עבור ל"מותר להעתיק": מה קורה, ולמה?'], 'דליפה במסלול נדיר מסתתרת בבדיקות קצרות ומפילה טיסה ארוכה; RAII סוגר אותה — בתנאי שהעתקה אסורה.'),
  w6_deliverables: MS(['Jetson, חצי דיוק, כל הבחירות מסומנות: מה הצוואר, ועומדים ביעד?', 'בטל "הקטנה לפני נרמול": מה הצוואר עכשיו?', 'עבור לדיוק מלא ובטל את התור של החדש: מה קורה להשהייה?', 'עבור למעבד בלבד: מה הצעד הראשון?'], 'הצוואר זז עם כל בחירה; הפסקה הרביעית של ההגשה היא "איפה הוא עכשיו" — מהמדידה.'),
  w6_plan6: MS(['קבע סף לשלב 3 לפני שתכניס מספר.', 'הכנס ירידה של 1.6 נקודות בשלב 3: מה הצעד הבא?', 'הכנס 35 מ"ש בשלב 4: לאיזה פרק חוזרים?'], 'כל שלב עם בדיקה במספר, והסף של שמונה ביטים — מראש.'),
  w6_report6: MS(['לחץ "דוגמה": פי כמה מהירה ההסקה בחצי דיוק, ופי כמה הצינור?', 'למה הפער? קרא את ההסבר מתחת לטבלה.', 'מלא את שורת הפתיחה לחומרה שלך, והעתק את הטבלה.'], 'הסקה בלבד ומקצה לקצה הם שני מספרים שונים; ומדד הזיהוי והחלפות הזהות הם חלק מהטבלה.'),
